<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {ArrowLeft,ArrowUpRight,MapPin,Navigation,Search} from 'lucide-vue-next'
import {journey,loadJourney,nameOf} from '../journey'
import DestinationActions from '../components/DestinationActions.vue'
const query=ref(''),category=ref('all'),showAll=ref(false)
const labels:Record<string,string>={scenic:'景区',night_visit:'夜市与夜游',restaurant:'餐饮地点',poi:'城市与园内地点',stage:'演出场地',entrance:'入口',rest:'休息地点',transport:'交通衔接'}
const places=computed(()=>journey.catalog.filter(x=>x.record.kind==='place'&&!x.record.is_demo&&!x.record.superseded_by&&x.record.business_status==='active'&&x.record.planning_status==='reference'&&x.record.place_type!=='stage'&&!(x.record.parent_place_id&&x.record.place_type==='poi')).filter(x=>category.value==='all'||x.record.place_type===category.value).filter(x=>(x.record.name+' '+(x.record.description||'')+' '+(x.record.aliases||[]).join(' ')).toLowerCase().includes(query.value.trim().toLowerCase())).sort((a,b)=>Number(b.record.longitude!=null)-Number(a.record.longitude!=null)))
const visible=computed(()=>showAll.value||query.value?places.value:places.value.slice(0,48))
onMounted(()=>loadJourney())
</script>
<template><div class="page place-detail-page"><RouterLink to="/" class="back-link"><ArrowLeft :size="16"/>返回发现</RouterLink><header class="editorial-title"><span class="tiny-caption">团队与公开采集资料</span><h1>找地方</h1><p>浏览介绍，收藏或加入素材篮。有坐标的地点可继续核算高德参考路程。</p></header><div class="explore-toolbar"><div class="discovery-tabs"><button v-for="item in [['all','全部'],['scenic','景区'],['night_visit','夜市'],['restaurant','餐饮'],['poi','地点']]" :key="item[0]" :class="{active:category===item[0]}" @click="category=item[0]">{{item[1]}}</button></div><label class="explore-search"><Search :size="17"/><input v-model="query" placeholder="搜索地点或别名" aria-label="搜索资料地点"></label></div><p class="source-note">{{places.length}} 处参考资料 · 坐标与营业信息按各条记录展示</p><div v-if="journey.loading" class="state">正在读取地点资料…</div><div class="poi-list"><article v-for="p in visible" :key="p.record.fact_id"><RouterLink :to="'/place/'+encodeURIComponent(p.record.fact_id)"><MapPin :size="17"/>{{p.record.name}}<ArrowUpRight :size="15"/></RouterLink><small>{{labels[p.record.place_type||'poi']||'地点'}}<template v-if="p.record.parent_place_id"> · {{nameOf(p.record.parent_place_id)}}</template> · {{p.record.longitude!=null?'已有坐标':'位置待补充'}}<template v-if="p.record.business_hours"> · {{p.record.business_hours}}</template></small><DestinationActions v-if="p.record.longitude!=null" :kind="p.record.place_type==='restaurant'?'place':'poi'" :id="p.record.fact_id" :name="p.record.name||'地点'"/><small v-else><Navigation :size="12"/> 仅作资料查询，位置补齐后再安排路线</small></article></div><button v-if="!showAll&&places.length>48&&!query" class="button secondary" @click="showAll=true">查看全部 {{places.length}} 处</button><div v-if="!journey.loading&&!visible.length" class="journey-empty"><p>没有找到相符的资料地点</p></div></div></template>
